qualified_questions.sparql_query:
PREFIX saref: <http://www.saref.etsi.org/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?device ?property1 ?property2 ?causality ?correlation
WHERE {
    ?device saref:measuresProperty ?property1 .
    ?device saref:measuresProperty ?property2 .
    FILTER (?property1 != ?property2) .
    OPTIONAL { 
        ?property1 s4envi:affectsProperty ?property2 . 
        BIND("causal" AS ?causality) 
    } .
    OPTIONAL { 
        ?property1 saref:relatesToProperty ?property2 . 
        BIND("correlated" AS ?correlation) 
    } .
    VALUES (?device) { (s4envi:Device) }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?environmentalObject ?description
WHERE {
    ?environmentalObject rdf:type s4envi:EnvironmentalObject .
    OPTIONAL { ?environmentalObject rdfs:label ?description . }
}

PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?component
WHERE {
    ?environmentalSystem s4envi:hasComponent ?component .
    FILTER NOT EXISTS {
        ?subComponent s4envi:isComponentOf ?component .
        ?subComponent s4envi:isComponentOf ?environmentalSystem .
    }
}

PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?device ?system1 ?component1 ?system2 ?component2
WHERE {
    ?device s4envi:isComponentOf ?system1 .
    ?device s4envi:isComponentOf ?system2 .
    FILTER (?system1 != ?system2) .
    ?system1 s4envi:hasComponent ?component1 .
    ?system2 s4envi:hasComponent ?component2 .
    FILTER (?component1 != ?component2) .
    FILTER EXISTS { ?system1 rdf:type [] . }
    FILTER EXISTS { ?system2 rdf:type [] . }
    FILTER EXISTS { ?device rdf:type [] . }
    FILTER EXISTS { ?component1 rdf:type [] . }
    FILTER EXISTS { ?component2 rdf:type [] . }
}

