PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX saref: <https://saref.etsi.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?creator ?contributor ?publisher
WHERE {
    <https://saref.etsi.org/saref4envi/> dcterms:creator ?creator .
    OPTIONAL { <https://saref.etsi.org/saref4envi/> dcterms:contributor ?contributor . }
    OPTIONAL { <https://saref.etsi.org/saref4envi/> dcterms:publisher ?publisher . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?profile
WHERE {
    <https://saref.etsi.org/saref4envi/> dcterms:creator ?creator .
    OPTIONAL { 
        ?creator foaf:homepage ?profile . 
    }
    OPTIONAL { 
        ?creator foaf:page ?profile .
    }
    FILTER (?profile != "")
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX saref: <https://saref.etsi.org/>

SELECT ?license
