PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://www.sensorml.com/ont/swe/property/S4EnvI/>
PREFIX saref: <https://www.sensorml.com/ont/swe/property/>

SELECT DISTINCT ?lightProperty
WHERE {
    ?lightProperty rdf:type s4envi:LightProperty.
    FILTER NOT EXISTS { 
        ?lightProperty rdf:type owl:NamedIndividual.
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://s4envi.euroscholars.eu/>
PREFIX saref: <https://www.saref.etsi.org/>

SELECT ?lightProperty ?relatedProperty
WHERE {
    ?lightProperty rdf:type s4envi:LightProperty .
    ?relatedProperty rdf:type saref:Property .
    FILTER (?lightProperty != ?relatedProperty) .
    VALUES ?lightProperty { s4envi:LightAbsorption s4envi:Phosphorescence s4envi:ReflectionOfLight s4envi:Illuminance s4envi:ScatteringOfLight s4envi:Fluorescence s4envi:Luminiscence s4envi:Irradiance s4envi:LightMagnitude }
    VALUES ?relatedProperty { s4envi:Frequency s4envi:Height s4envi:Period }
}

PREFIX saref: <http://www.saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?device ?property1 ?property2
WHERE {
    ?device rdf:type ?type .
    ?type rdfs:subClassOf* saref:Device .
    ?device saref:hasProperty ?property1 .
    ?device saref:hasProperty ?property2 .
    FILTER (?property1 != ?property2) .
    {
        { ?property1 rdf:type s4envi:LightProperty }
        UNION
        { ?property1 rdfs:subClassOf* s4envi:LightProperty }
    } .
    {
        { ?property2 rdf:type s4envi:LightProperty }
        UNION
        { ?property2 rdfs:subClassOf* s4envi:LightProperty }
    } .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://saref.etsi.org/s4envi/>
PREFIX saref: <http://saref.etsi.org/>

SELECT ?device
WHERE {
    ?device rdf:type ?type .
    ?type rdfs:subClassOf* saref:Device .
    OPTIONAL { ?device s4envi:hasGeometry ?geometry . }
    OPTIONAL { ?device s4envi:hasLightProperty ?lightProperty . }
    FILTER(EXISTS { ?device s4envi:hasGeometry ?geometry } && EXISTS { ?device s4envi:hasLightProperty ?lightProperty })
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://s4envi.example/>
PREFIX saref: <http://saref.example/>

SELECT ?x
WHERE {
    ?x rdf:type s4envi:LightProperty .
    FILTER NOT EXISTS { ?x rdf:type owl:NamedIndividual }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX saref: <https://www.saref.etsi.org/>

SELECT ?class
WHERE {
    ?class rdf:type owl:Class .
    ?class rdfs:subClassOf* saref:Property .
    {
        { ?class rdf:type s4envi:LightProperty }
        UNION
        { ?instance rdf:type ?class . 
          { ?instance rdf:type s4envi:Luminiscence } 
          UNION 
          { ?instance rdf:type s4envi:ReflectionOfLight } 
        }
    }
    FILTER (?class = s4envi:LightProperty)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://www.saref.eu/s4envi/>
PREFIX saref: <http://www.saref.eu/>

SELECT ?unit
WHERE {
    { 
        ?unit rdf:type s4envi:FrequencyUnit .
    } UNION {
        ?unit rdf:type ?type .
        ?type rdfs:subClassOf* s4envi:FrequencyUnit .
    }
    FILTER (?unit != saref:UnitOfMeasure)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://www.sensorml.com/ont/swe/physical/units/>
PREFIX saref: <https://www.saref.etsi.org/core/>

SELECT ?unit
WHERE {
    { ?unit rdf:type s4envi:FrequencyUnit }
    UNION
    { ?unit rdf:type s4envi:TimeUnit .
      FILTER NOT EXISTS { ?unit rdf:type s4envi:LengthUnit } 
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?object ?description
WHERE {
    ?object dcterms:description ?description .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?title
WHERE {
    ?resource dcterms:title ?title .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (COUNT(DISTINCT ?resource) AS ?count)
WHERE {
    ?resource dcterms:creator ?creator .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?resource
WHERE {
    ?resource rdf:type ?type .
    FILTER NOT EXISTS { ?resource dcterms:contributor [] }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?resource ?contributor ?modification 
WHERE {
    ?resource dcterms:creator ?contributor .
    ?resource dcterms:modified ?modification .
    OPTIONAL { ?resource dcterms:contributor ?contributor2 . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?resource
WHERE {
    ?resource rdf:type ?type .
    FILTER NOT EXISTS { ?resource dcterms:description ?description }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?device1 ?relation ?device2
WHERE {
    ?device1 rdf:type s4envi:Device .
    ?device2 rdf:type s4envi:Device .
    FILTER (?device1 != ?device2) .
    {
        { ?device1 rdf:type saref:Sensor . }
        UNION
        { ?device1 rdf:type s4envi:Actuator . }
    } .
    {
        { ?device2 rdf:type saref:Sensor . }
        UNION
        { ?device2 rdf:type s4envi:Actuator . }
    } .
    ?relation rdf:type rdf:Property .
    ?device1 ?relation ?device2 .
}

PREFIX s4envi: <http://s4envi.example/>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?geometry ?physicalObject
WHERE {
    ?physicalObject rdf:type s4envi:PhysicalObject .
    ?geometry rdf:type wgs84:Point .
    FILTER EXISTS {
        ?device rdf:type s4envi:Device .
        { 
            ?physicalObject rdfs:subClassOf ?device . 
        }
        UNION
        { 
            ?device rdfs:subClassOf ?physicalObject . 
        }
        UNION
        {
          ?physicalObject rdfs:subClassOf* ?device .
        }
        UNION
        {
          ?device rdfs:subClassOf* ?physicalObject .
        }
    }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://www.s4envi.eu/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?measurement
WHERE {
    ?measurement rdf:type saref:Measurement .
    FILTER NOT EXISTS { 
        ?measurement rdf:type s4envi:FrequencyMeasurement .
    } .
    FILTER NOT EXISTS { 
        ?measurement rdf:type s4envi:HeightMeasurement .
    } .
}
